// generated by tools/build_verse_manifests.js from jst_english.js — Dual-view English for the chapters of jst_verses/jstmatt.js
registerEnglish([["Matthew",1,1,"And when he had gathered all the chief priests, and scribes of the people together, he demanded of them, saying, Where is the place that is written of by the prophets, in which Christ should be born? For he greatly feared, yet he believed not the prophets."],["Matthew",1,2,"And they said unto him, It is written by the prophets, that he should be born in Bethlehem of Judea, for thus have they said,"],["Matthew",1,3,"The word of the Lord came unto us, saying, And thou Bethlehem, which lieth in the land of Judea, in thee shall be born a prince, which art not the least among the princes of Judea; for out of thee shall come the Messiah, who shall save my people Israel."],["Matthew",1,4,"And it came to pass that Jesus grew up with his brethren, and waxed strong, and waited upon the Lord for the time of his ministry to come."],["Matthew",1,5,"And he served under his father, and he spake not as other men, neither could he be taught; for he needed not that any man should teach him."],["Matthew",1,6,"And after many years, the hour of his ministry drew nigh."],["Matthew",2,1,"Then Jesus was led up of the Spirit, into the wilderness, to be with God."],["Matthew",2,2,"Then Jesus was taken up into the holy city, and the Spirit setteth him on the pinnacle of the temple."],["Matthew",2,3,"Then the devil came unto him and said, If thou be the Son of God, cast thyself down, for it is written, He shall give his angels charge concerning thee, and in their hands they shall bear thee up, lest at any time thou dash thy foot against a stone."],["Matthew",2,4,"And again, Jesus was in the Spirit, and it taketh him up into an exceeding high mountain, and showeth him all the kingdoms of the world and the glory of them."],["Matthew",2,5,"And the devil came unto him again, and said, All these things will I give unto thee, if thou wilt fall down and worship me."],["Matthew",2,6,"And now Jesus knew that John was cast into prison, and he sent angels, and, behold, they came and ministered unto him."],["Matthew",3,1,"Whosoever, therefore, shall break one of these least commandments, and shall teach men so to do, he shall in no wise be saved in the kingdom of heaven; but whosoever shall do and teach these commandments of the law until it be fulfilled, the same shall be called great, and shall be saved in the kingdom of heaven."],["Matthew",4,1,"And suffer us not to be led into temptation, but deliver us from evil."],["Matthew",4,2,"The light of the body is the eye; if therefore thine eye be single to the glory of God, thy whole body shall be full of light."],["Matthew",4,3,"And, again, I say unto you, Go ye into the world, and care not for the world; for the world will hate you, and will persecute you, and will turn you out of their synagogues."],["Matthew",4,4,"Nevertheless, ye shall go forth from house to house, teaching the people; and I will go before you."],["Matthew",4,5,"And your heavenly Father will provide for you, whatsoever things ye need for food, what ye shall eat; and for raiment, what ye shall wear or put on."],["Matthew",5,1,"Now these are the words which Jesus taught his disciples that they should say unto the people."],["Matthew",5,2,"Judge not unrighteously, that ye be not judged; but judge righteous judgment."],["Matthew",5,3,"And again, ye shall say unto them, Why is it that thou beholdest the mote that is in thy brother’s eye, but considerest not the beam that is in thine own eye?"],["Matthew",5,4,"Or how wilt thou say to thy brother, Let me pull out the mote out of thine eye; and canst not behold a beam in thine own eye?"],["Matthew",5,5,"And Jesus said unto his disciples, Beholdest thou the scribes, and the Pharisees, and the priests, and the Levites? They teach in their synagogues, but do not observe the law, nor the commandments; and all have gone out of the way, and are under sin."],["Matthew",5,6,"Go thou and say unto them, Why teach ye men the law and the commandments, when ye yourselves are the children of corruption?"],["Matthew",5,7,"Say unto them, Ye hypocrites, first cast out the beam out of thine own eye; and then shalt thou see clearly to cast out the mote out of thy brother’s eye."],["Matthew",6,1,"Then said the Pharisees unto him, Why will ye not receive us with our baptism, seeing we keep the whole law?"],["Matthew",6,2,"But Jesus said unto them, Ye keep not the law. If ye had kept the law, ye would have received me, for I am he who gave the law."],["Matthew",6,3,"I receive not you with your baptism, because it profiteth you nothing."],["Matthew",6,4,"For when that which is new is come, the old is ready to be put away."],["Matthew",7,1,"But the days will come, when the violent shall have no power; for all the prophets and the law prophesied that it should be thus until John."],["Matthew",7,2,"Yea, as many as have prophesied have foretold of these days."],["Matthew",7,3,"And if ye will receive it, verily, he was the Elias, who was for to come and prepare all things."],["Matthew",8,1,"Then came some of the scribes and said unto him, Master, it is written that, Every sin shall be forgiven; but ye say, Whosoever speaketh against the Holy Ghost shall not be forgiven. And they asked him, saying, How can these things be?"],["Matthew",8,2,"And he said unto them, When the unclean spirit is gone out of a man, he walketh through dry places, seeking rest and findeth none; but when a man speaketh against the Holy Ghost, then he saith, I will return into my house from whence I came out; and when he is come, he findeth him empty, swept and garnished; for the good spirit leaveth him unto himself."],["Matthew",9,1,"The harvest is the end of the world, or the destruction of the wicked."],["Matthew",9,2,"The reapers are the angels, or the messengers sent of heaven."],["Matthew",9,3,"As, therefore, the tares are gathered and burned in the fire, so shall it be in the end of this world, or the destruction of the wicked."],["Matthew",9,4,"For in that day, before the Son of man shall come, he shall send forth his angels and messengers of heaven."],["Matthew",9,5,"And they shall gather out of his kingdom all things that offend, and them which do iniquity, and shall cast them out among the wicked; and there shall be wailing and gnashing of teeth."],["Matthew",9,6,"For the world shall be burned with fire."],["Matthew",10,1,"Then said Jesus unto his disciples, If any man will come after me, let him deny himself, and take up his cross and follow me."],["Matthew",10,2,"And now for a man to take up his cross, is to deny himself all ungodliness, and every worldly lust, and keep my commandments."],["Matthew",10,3,"Break not my commandments for to save your lives; for whosoever will save his life in this world, shall lose it in the world to come."],["Matthew",10,4,"And whosoever will lose his life in this world, for my sake, shall find it in the world to come."],["Matthew",10,5,"Therefore, forsake the world, and save your souls; for what is a man profited, if he shall gain the whole world, and lose his own soul? Or what shall a man give in exchange for his soul?"],["Matthew",11,1,"And Jesus answered and said unto them, Elias truly shall first come, and restore all things, as the prophets have written."],["Matthew",11,2,"And again I say unto you that Elias has come already, concerning whom it is written, Behold, I will send my messenger, and he shall prepare the way before me; and they knew him not, and have done unto him, whatsoever they listed."],["Matthew",11,3,"Likewise shall also the Son of man suffer of them."],["Matthew",11,4,"But I say unto you, Who is Elias? Behold, this is Elias, whom I send to prepare the way before me."],["Matthew",11,5,"Then the disciples understood that he spake unto them of John the Baptist, and also of another who should come and restore all things, as it is written by the prophets."],["Matthew",12,1,"For the Son of man is come to save that which was lost, and to call sinners to repentance; but these little ones have no need of repentance, and I will save them."],["Matthew",13,1,"Then were there brought unto him little children, that he should put his hands on them and pray. And the disciples rebuked them, saying, There is no need, for Jesus hath said, Such shall be saved."],["Matthew",14,1,"For he that believed not John concerning me, cannot believe me, except he first repent."],["Matthew",14,2,"And when the chief priests and Pharisees had heard his parables, they perceived that he spake of them."],["Matthew",14,3,"And they said among themselves, Shall this man think that he alone can spoil this great kingdom? And they were angry with him."],["Matthew",14,4,"But when they sought to lay hands on him, they feared the multitude, because they learned that the multitude took him for a prophet."],["Matthew",14,5,"And now his disciples came to him, and Jesus said unto them, Marvel ye at the words of the parable which I spake unto them?"],["Matthew",14,6,"Verily, I say unto you, I am the stone, and those wicked ones reject me."],["Matthew",14,7,"I am the head of the corner. These Jews shall fall upon me, and shall be broken."],["Matthew",15,1,"And call no one your creator upon the earth, or your heavenly Father; for one is your creator and heavenly Father, even he who is in heaven."],["Matthew",16,1,"And as they were eating, Jesus took bread and brake it, and blessed it, and gave to his disciples, and said, Take, eat; this is in remembrance of my body which I give a ransom for you."],["Matthew",16,2,"For this is in remembrance of my blood of the new testament, which is shed for as many as shall believe on my name, for the remission of their sins."],["Matthew",16,3,"And I give unto you a commandment, that ye shall observe to do the things which ye have seen me do, and bear record of me even unto the end."],["Matthew",17,1,"Then Judas, who had betrayed him, when he saw that he was condemned, repented himself, and brought again the thirty pieces of silver to the chief priests and elders,"],["Matthew",17,2,"Saying, I have sinned in that I have betrayed the innocent blood."],["Matthew",17,3,"And he cast down the pieces of silver in the temple, and departed, and went, and hanged himself on a tree. And straightway he fell down, and his bowels gushed out, and he died."]]);
